int main(void)
{
  heif_context* ctx = heif_context_alloc();
  heif_error err = heif_context_read_from_memory(ctx, image_data,
                                                 sizeof(image_data), NULL);
  if (err.code != heif_error_Ok) {
    fprintf(stderr, "read: %s\n", err.message);
    return 1;
  }

  heif_image_handle* handle = NULL;
  err = heif_context_get_primary_image_handle(ctx, &handle);
  if (err.code != heif_error_Ok) {
    fprintf(stderr, "handle: %s\n", err.message);
    heif_context_free(ctx);
    return 1;
  }

  heif_image* img = NULL;
  err = heif_decode_image(handle, &img, heif_colorspace_undefined,
                          heif_chroma_undefined, NULL);
  if (err.code != heif_error_Ok) {
    fprintf(stderr, "decode: %s\n", err.message);
    heif_image_handle_release(handle);
    heif_context_free(ctx);
    return 1;
  }

  int w = heif_image_get_primary_width(img);
  int h = heif_image_get_primary_height(img);
  printf("decoded %dx%d\n", w, h);

  /* Attach a depth data channel at half the image resolution. */
  err = heif_image_add_plane(img, heif_channel_depth, w / 2, h / 2, 8);
  if (err.code != heif_error_Ok) {
    fprintf(stderr, "add_plane: %s\n", err.message);
    heif_image_release(img);
    heif_image_handle_release(handle);
    heif_context_free(ctx);
    return 1;
  }

  /* Crop the full image; every plane is copied row by row. */
  err = heif_image_crop(img, 0, 0, 0, 0);
  printf("crop: code=%d subcode=%d message=%s\n", err.code, err.subcode,
         err.message);

  heif_image_release(img);
  heif_image_handle_release(handle);
  heif_context_free(ctx);
  return 0;
}
